//! The contracts a Safe's creation may depend on, and the runtime code each
//! must have (`data/known-contracts.json`, generated by
//! `verify/known_contracts.py`: Safe's own deployments from safe-deployments
//! at a pinned commit, plus module contracts observed identical on several
//! chains).

use std::collections::HashMap;
use std::sync::OnceLock;

use alloy::primitives::{Address, B256};
use serde::{Deserialize, Serialize};

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct KnownContract {
    pub address: Address,
    pub code_hash: B256,
    pub name: String,
    pub source: String,
}

/// What a known contract IS, from its name — which decides the roles it may
/// play in a creation. Anything not listed (CreateCall, SignMessageLib,
/// SimulateTxAccessor, migrations, CreateAndAddModules, …) is `Other`: known
/// code, but no role in a setup.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub enum Kind {
    ProxyFactory,
    Singleton,
    SingletonL2,
    FallbackHandler,
    MultiSend,
    MultiSendCallOnly,
    SafeToL2Setup,
    ModuleSetup,
    /// Safe's 4337 module: a module, and the fallback handler it is paired with.
    Module4337,
    PasskeySharedSigner,
    PasskeySignerFactory,
    PasskeySignerSingleton,
    Other,
}

impl KnownContract {
    pub fn kind(&self) -> Kind {
        match self.name.split_whitespace().next().unwrap_or("") {
            "ProxyFactory" | "GnosisSafeProxyFactory" | "SafeProxyFactory" => Kind::ProxyFactory,
            "GnosisSafe" | "Safe" => Kind::Singleton,
            "GnosisSafeL2" | "SafeL2" => Kind::SingletonL2,
            "CompatibilityFallbackHandler" | "DefaultCallbackHandler" | "TokenCallbackHandler"
            | "ExtensibleFallbackHandler" => Kind::FallbackHandler,
            "MultiSend" => Kind::MultiSend,
            "MultiSendCallOnly" => Kind::MultiSendCallOnly,
            "SafeToL2Setup" => Kind::SafeToL2Setup,
            "SafeModuleSetup" => Kind::ModuleSetup,
            "Safe4337Module" => Kind::Module4337,
            "SafeWebAuthnSharedSigner" => Kind::PasskeySharedSigner,
            "SafeWebAuthnSignerFactory" => Kind::PasskeySignerFactory,
            "SafeWebAuthnSignerSingleton" => Kind::PasskeySignerSingleton,
            _ => Kind::Other,
        }
    }

    /// `(major, minor)` of a Safe contract, from its name ("Safe 1.4.1 (canonical)").
    pub fn safe_version(&self) -> Option<(u8, u8)> {
        let v = self.name.split_whitespace().nth(1)?;
        let mut parts = v.split('.');
        Some((parts.next()?.parse().ok()?, parts.next()?.parse().ok()?))
    }
}

#[derive(Debug, Default)]
pub struct KnownContracts {
    by_address: HashMap<Address, Vec<KnownContract>>,
}

#[derive(Deserialize)]
struct File {
    contracts: Vec<KnownContract>,
}

impl KnownContracts {
    /// The table shipped with this crate.
    pub fn embedded() -> &'static Self {
        static TABLE: OnceLock<KnownContracts> = OnceLock::new();
        TABLE.get_or_init(|| {
            Self::from_json(include_str!("../data/known-contracts.json")).expect("embedded known-contracts.json")
        })
    }

    pub fn from_json(json: &str) -> Result<Self, serde_json::Error> {
        let file: File = serde_json::from_str(json)?;
        let mut by_address: HashMap<Address, Vec<KnownContract>> = HashMap::new();
        for c in file.contracts {
            by_address.entry(c.address).or_default().push(c);
        }
        Ok(Self { by_address })
    }

    /// Every acceptable code for an address; empty when the address is unknown.
    pub fn at(&self, address: Address) -> &[KnownContract] {
        self.by_address.get(&address).map(Vec::as_slice).unwrap_or(&[])
    }

    /// The known contract this code is, at this address.
    pub fn matching(&self, address: Address, code_hash: B256) -> Option<&KnownContract> {
        self.at(address).iter().find(|c| c.code_hash == code_hash)
    }

    /// Whether this address is known as one of `kinds` (by address only; the
    /// code found on a chain is checked separately).
    pub fn is(&self, address: Address, kinds: &[Kind]) -> bool {
        self.at(address).iter().any(|c| kinds.contains(&c.kind()))
    }

    pub fn len(&self) -> usize {
        self.by_address.values().map(Vec::len).sum()
    }

    pub fn is_empty(&self) -> bool {
        self.by_address.is_empty()
    }
}
